import json,glob,os,re,hashlib,html
root='/mnt/data/gmri-log-review'
entries=[];convos=[]
for f in sorted(glob.glob(root+'/chatgpt-*.json')):
    data=json.load(open(f,encoding='utf-8'))
    hash_file=hashlib.sha256(open(f,'rb').read()).hexdigest()
    convos.append({'id':data['conversationId'],'title':data['title'],'url':data['url'],'exportedAt':data['exportedAt'],'messages':data['messageCount'],'source':os.path.basename(f),'sha256':hash_file,'completeness':data.get('completeness'),'branchMode':data.get('branchMode')})
    for msg in data['messages']:
        s=msg.get('text','')
        entries.append({'conv':data['conversationId'],'i':msg['index'],'role':msg['role'],'text':s,'sha256':hashlib.sha256(s.encode('utf-8')).hexdigest(),'chars':len(s)})
assert len(convos)==12 and len(entries)==1626
payload={'convos':convos,'entries':entries}
encoded=json.dumps(payload,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')
css=r'''
