js=r'''
const D=__DATA__;
const convmap=new Map(D.convos.map(c=>[c.id,c]));
const msgsByConv=new Map(D.convos.map(c=>[c.id,[]]));
for(const e of D.entries)msgsByConv.get(e.conv).push(e);
const $=s=>document.querySelector(s), mk=(tag,cls,txt)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(txt!==undefined)n.textContent=txt;return n};
const getname=e=>convmap.get(e.conv).title+' #'+e.i;
let selected=null,activeQuery='',activeRole='all',shown=0,matched=[],maxRender=35,showFull=false;
function setStatus(s){$('#status').textContent=s}
function makeMessage(e){const c=convmap.get(e.conv),wrap=mk('section','message');wrap.dataset.role=e.role;wrap.id='m-'+e.conv+'-'+e.i;
 const top=mk('div','row');const lab=mk('span','badge '+(e.role==='user'?'user':''),e.role.toUpperCase());top.append(lab,mk('strong','',`#${e.i} · ${c.title}`));const jump=mk('a','', 'Original chat');jump.href=c.url;jump.target='_blank';jump.rel='noreferrer';top.append(jump);wrap.append(top);
 const pre=mk('pre',e.text.length>3500&&!showFull?'cuttxt':'',e.text);wrap.append(pre);
 if(e.text.length>3500){const toggle=mk('button','',showFull?'Collapse message':'Read full message ('+e.text.length.toLocaleString()+' chars)');toggle.addEventListener('click',()=>{pre.classList.toggle('cuttxt');toggle.textContent=pre.classList.contains('cuttxt')?'Read full message ('+e.text.length.toLocaleString()+' chars)':'Collapse message'});wrap.append(toggle)}
 const details=mk('details','');const summary=mk('summary','meta',`SHA-256 of exact message text · ${e.chars.toLocaleString()} characters`);const l=mk('div','meta',e.sha256);details.append(summary,l);wrap.append(details);return wrap;}
function renderConvs(){const list=$('#conversations');list.replaceChildren();for(const c of D.convos){const b=mk('button','conv'+(selected===c.id?' active':''),c.title);b.append(mk('small','',c.messages+' messages · '+c.completeness+' '+c.branchMode));b.addEventListener('click',()=>openConv(c.id));list.append(b)}}
function openConv(id,highlight){selected=id;activeQuery='';$('#search').value='';renderConvs();$('#searchResults').classList.add('hide');$('#conversationView').classList.remove('hide');const c=convmap.get(id);$('#convTitle').textContent=c.title;$('#convInfo').textContent=c.messages+' messages · exported '+c.exportedAt+' · source '+c.source;
$('#origLink').href=c.url;$('#sourceHash').textContent='Original export SHA-256: '+c.sha256;shown=0;$('#transcript').replaceChildren();if(highlight){const ms=msgsByConv.get(id);const pos=ms.findIndex(x=>x.i===highlight);shown=Math.min(ms.length,Math.max(maxRender,pos+8));}appendBatch(true);if(highlight){const el=document.getElementById('m-'+id+'-'+highlight);if(el){el.classList.add('selected');el.scrollIntoView({behavior:'instant',block:'center'})}}}
function appendBatch(first=false){const ms=msgsByConv.get(selected)||[],start=first?0:shown,end=Math.min(ms.length,first?shown:shown+maxRender);for(let j=start;j<end;j++)$('#transcript').append(makeMessage(ms[j]));shown=end;$('#more').style.display=shown<ms.length?'inline-block':'none';setStatus(`Reading: ${convmap.get(selected).title} · showing ${shown} of ${ms.length} messages`)}
function openContext(e){selected=e.conv;renderConvs();$('#searchResults').classList.add('hide');$('#conversationView').classList.remove('hide');const c=convmap.get(e.conv);$('#convTitle').textContent=c.title+' · context around #'+e.i;$('#convInfo').textContent='Exact adjacent messages from original JSON export';$('#origLink').href=c.url;$('#sourceHash').textContent='Original export SHA-256: '+c.sha256;
const all=msgsByConv.get(e.conv),p=all.findIndex(x=>x.i===e.i),start=Math.max(0,p-5),end=Math.min(all.length,p+6);$('#transcript').replaceChildren(...all.slice(start,end).map(makeMessage));shown=0;$('#more').style.display='none';const readAll=mk('button','', 'Read entire conversation from message #1');readAll.addEventListener('click',()=>openConv(e.conv,e.i));$('#transcript').prepend(readAll);setStatus('Source context: '+c.title+' #'+e.i+' ('+(start+1)+'–'+end+')');const node=document.getElementById('m-'+e.conv+'-'+e.i);if(node)node.classList.add('selected');}
function search(){activeQuery=$('#search').value.trim().toLowerCase();activeRole=$('#role').value;const terms=activeQuery.split(/\s+/).filter(Boolean);matched=D.entries.filter(e=>(activeRole==='all'||e.role===activeRole)&&terms.every(t=>e.text.toLowerCase().includes(t)));$('#searchResults').classList.remove('hide');$('#conversationView').classList.add('hide');$('#matchCount').textContent=`${matched.length.toLocaleString()} matching messages · original text intact`;$('#results').replaceChildren();shown=0;loadResults();setStatus('Search across '+D.entries.length.toLocaleString()+' messages · '+matched.length+' matched')}
function loadResults(){let upto=Math.min(matched.length,shown+100);for(let i=shown;i<upto;i++){const e=matched[i],b=mk('button','item');const lab=mk('div','row');lab.append(mk('span','badge '+(e.role==='user'?'user':''),e.role.toUpperCase()),mk('strong','',getname(e)));b.append(lab);const q=activeQuery.split(/\s+/)[0],p=q?e.text.toLowerCase().indexOf(q):0,st=Math.max(0,p-160);let snippet=e.text.slice(st,st+520);if(st)snippet='…'+snippet;if(st+520<e.text.length)snippet+='…';b.append(mk('div','excerpt',snippet));b.addEventListener('click',()=>openContext(e));$('#results').append(b)}shown=upto;$('#moreSearch').style.display=shown<matched.length?'inline-block':'none'}
$('#search').addEventListener('keydown',e=>{if(e.key==='Enter')search()});$('#submitSearch').addEventListener('click',search);$('#role').addEventListener('change',()=>{if(!$('#searchResults').classList.contains('hide'))search()});$('#more').addEventListener('click',()=>appendBatch());$('#moreSearch').addEventListener('click',loadResults);$('#all').addEventListener('click',()=>{selected=null;renderConvs();$('#search').value='';search()});$('#expandAll').addEventListener('click',()=>{showFull=!showFull;$('#expandAll').textContent=showFull?'Default long-message collapse':'Expand long messages by default';if(selected&&$('#conversationView').classList.contains('hide')===false)openConv(selected)});
$('#convoCount').textContent=D.convos.length;$('#messageCount').textContent=D.entries.length.toLocaleString();renderConvs();openConv(D.convos[0].id);
